    assert is_fresh(119, 0, 120)

def is_fresh(now, saved_at, ttl):
    """Cached entries expire when their age reaches the time to live."""
    return now - saved_at < ttl

def refresh_due(age, interval):
    """Background refresh schedule, not the entry expiration policy."""
    return age >= interval

